SELECT symbol, id, observed_at, price, delivery_status, outcome_reason, created_at FROM market_price_event WHERE (symbol='SHIBUSDT' AND observed_at BETWEEN '2026-10-10 21:45:00' AND '2026-10-10 21:45:31') OR (symbol='PEPEUSDT' AND observed_at BETWEEN '2026-10-10 17:50:00' AND '2026-10-10 17:50:13') OR (symbol='PEPEUSDT' AND observed_at BETWEEN '2026-10-10 22:45:00' AND '2026-10-10 22:45:09') OR (symbol='ENAUSDT' AND observed_at BETWEEN '2026-10-11 05:40:00' AND '2026-10-11 05:40:10') ORDER BY symbol, observed_at LIMIT 200;